#scene{position:fixed;inset:0}
canvas{display:block}
#hud{position:fixed;inset:0;pointer-events:none;display:flex;flex-direction:column}
#top{
  display:flex;align-items:baseline;gap:14px;padding:18px 22px 0;
  background:linear-gradient(180deg,rgba(7,5,12,.9),rgba(7,5,12,0));
}
#top h1{font-size:22px;font-weight:600;letter-spacing:.04em}
#top h1 em{color:var(--gold);font-style:italic}
#top .sub{font-family:"Space Mono",monospace;font-size:10px;color:var(--dim);letter-spacing:.18em;text-transform:uppercase}
#search{
  pointer-events:auto;margin:12px 22px 0;position:relative;width:min(420px,60vw);
}
#search input{
  width:100%;background:rgba(20,15,30,.75);border:1px solid var(--line);
  color:var(--ink);font-family:"Space Mono",monospace;font-size:13px;
  padding:10px 14px;border-radius:2px;outline:none;
}
#search input:focus{border-color:var(--gold)}
#suggest{
  position:absolute;top:100%;left:0;right:0;background:#120d1e;
  border:1px solid var(--line);border-top:none;max-height:260px;overflow:auto;
  font-family:"Space Mono",monospace;font-size:12px;display:none;
}
#suggest div{padding:7px 14px;cursor:pointer;color:var(--dim)}
#suggest div:hover{background:#1d1530;color:var(--ink)}
#panel{
  pointer-events:auto;position:fixed;right:22px;top:70px;width:300px;
  max-height:calc(100vh - 100px);overflow:auto;
  background:rgba(13,9,20,.88);border:1px solid var(--line);border-radius:3px;
  padding:20px 20px 16px;backdrop-filter:blur(6px);
  display:none;
}
#panel.open{display:block}
#panel .word{font-size:34px;font-weight:600;line-height:1.05}
#panel .tema{
  font-family:"Space Mono",monospace;font-size:10px;letter-spacing:.2em;
  text-transform:uppercase;color:var(--gold);margin:6px 0 14px;
}
#panel h3{
  font-family:"Space Mono",monospace;font-size:10px;letter-spacing:.2em;
  text-transform:uppercase;color:var(--dim);margin:14px 0 8px;
  border-top:1px solid var(--line);padding-top:12px;
}
#panel h3:first-of-type{border-top:none;padding-top:0;margin-top:0}
#panel ul{list-style:none}
#panel li{margin:2px 0}
#panel li button{
  background:none;border:none;color:var(--ink);cursor:pointer;
  font-family:"Cormorant Garamond",serif;font-size:17px;text-align:left;
  padding:2px 0;
}
#panel li button:hover{color:var(--gold)}
#panel .count{font-family:"Space Mono",monospace;font-size:10px;color:var(--dim)}
#panel .close{
  position:absolute;top:10px;right:12px;background:none;border:none;
  color:var(--dim);font-size:18px;cursor:pointer;font-family:"Space Mono",monospace;
}
#panel .close:hover{color:var(--ink)}
#stats{
  position:fixed;left:22px;bottom:18px;font-family:"Space Mono",monospace;
  font-size:10px;color:var(--dim);letter-spacing:.12em;line-height:1.9;
}
#stats b{color:var(--ink);font-weight:400}
#hint{
  position:fixed;right:22px;bottom:18px;font-family:"Space Mono",monospace;
  font-size:10px;color:var(--dim);letter-spacing:.12em;text-align:right;
}
@media (max-width:700px){
  #panel{left:12px;right:12px;width:auto;top:auto;bottom:12px;max-height:45vh}
  #hint{display:none}
}
</style>
